package dev.szx.dimensionworks.rpmlimit;
import com.simibubi.create.content.kinetics.base.KineticBlockEntity; import net.minecraft.server.level.ServerPlayer; import net.minecraft.world.level.block.entity.BlockEntity; import net.minecraftforge.event.TickEvent; import net.minecraftforge.event.entity.player.PlayerEvent; import net.minecraftforge.event.level.BlockEvent; import net.minecraftforge.eventbus.api.SubscribeEvent;
public final class RpmForgeEvents { @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent e){RpmLimitManager.init(e.getEntity());} @SubscribeEvent public static void tick(TickEvent.PlayerTickEvent e){if(e.phase==TickEvent.Phase.END&&e.player instanceof ServerPlayer p)RpmLimitManager.refresh(p.server.getPlayerList().getPlayers(),p.server.getTickCount());} @SubscribeEvent public static void place(BlockEvent.EntityPlaceEvent e){if(e.getEntity() instanceof ServerPlayer p){BlockEntity be=e.getLevel().getBlockEntity(e.getPos());if(be instanceof KineticBlockEntity k)RpmLimitManager.setOwner(k,p.getUUID());}} }
